<script setup>
import {ref,computed,onMounted} from 'vue'
const service=ref('MS Project 교육'),goal=ref(''),output=ref(''),timing=ref(''),status=ref('')
const options=['MS Project 교육','프로젝트 관리 컨설팅','공정표 작성 대행','AI 교육','ChatGPT 컨설팅','Microsoft Copilot 컨설팅']
onMounted(()=>{const q=new URLSearchParams(window.location.search).get('service');if(options.includes(q))service.value=q})
const draft=computed(()=>['안녕하세요. 피엠오피스 교육·컨설팅을 문의드립니다.','','관심 분야: '+service.value,'해결할 과제·교육 대상: '+(goal.value||'상담 시 협의'),'필요 산출물·사용 환경: '+(output.value||'상담 시 협의'),'희망 일정·제출일: '+(timing.value||'협의'),'','수행 범위와 준비 자료를 안내 부탁드립니다.'].join('\n'))
const mail=computed(()=>'mailto:nam@pmoffice.co.kr?subject='+encodeURIComponent('[피엠오피스 문의] '+service.value)+'&body='+encodeURIComponent(draft.value))
async function copy(){try{await navigator.clipboard.writeText(draft.value);status.value='문의 초안을 복사했습니다.'}catch{status.value='문의 초안을 선택하여 복사하십시오.'}}
</script>
<template><section id="service-inquiry" class="inquiry-panel"><div class="section-inner release-section"><div class="release-heading"><span class="consult-eyebrow">교육·컨설팅 문의</span><h2>필요한 교육과 산출물,<br>희망 일정을 알려주십시오.</h2><p>현재 자료와 해결할 과제를 기준으로 지원 범위를 제안하겠습니다.</p></div><div class="inquiry-grid"><div class="inquiry-inputs"><label>관심 분야<select v-model="service"><option v-for="o in options" :key="o">{{o}}</option></select></label><label>해결할 과제·교육 대상<textarea v-model="goal" maxlength="800" rows="3" placeholder="담당 업무, 교육 대상과 필요한 지원"></textarea></label><label>필요 산출물·사용 환경<input v-model="output" maxlength="250" placeholder="예: MS Project·Excel 공정표, 제출용 PDF"></label><label>희망 일정·제출일<input v-model="timing" maxlength="180" placeholder="정해지지 않았다면 비워두십시오."></label></div><div class="inquiry-result"><h3>문의 초안</h3><textarea readonly :value="draft" rows="12" aria-label="교육·컨설팅 문의 초안"></textarea><div class="actions"><a class="btn primary" :href="mail">메일 앱에서 보내기 ↗</a><button type="button" class="btn secondary" @click="copy">초안 복사</button></div><p role="status">{{status}}</p><div class="contact-links"><a href="mailto:nam@pmoffice.co.kr">nam@pmoffice.co.kr</a><a href="tel:025328060">02-532-8060</a></div></div></div></div></section></template>
